<?php
require_once __DIR__ . '/db_connect.php';  echo "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Receipt Lookup Test</title>";
echo "<style>body{font-family:Arial,sans-serif;padding:20px;} table{border-collapse:collapse;width:100%;margin-top:20px;} th,td{border:1px solid #ddd;padding:8px;text-align:left;} th{background:#002F70;color:white;} a{color:#002F70;}</style></head><body>";  echo "<h2>Receipt Lookup Test</h2>";  try {  // Get all merchandise transactions  $stmt = $pdo->query("  SELECT id, transaction_id, customer_name, total_amount, validation_status, created_at  FROM merchandise_transactions  ORDER BY id DESC  LIMIT 20  ");  $txns = $stmt->fetchAll(PDO::FETCH_ASSOC);  echo "<p>Total transactions found: <strong>" . count($txns) . "</strong></p>";  if (count($txns) > 0) {  echo "<table>";  echo "<tr><th>DB ID</th><th>Transaction ID</th><th>Customer</th><th>Amount</th><th>Status</th><th>Date</th><th>Receipt Link</th></tr>";  foreach ($txns as $txn) {  $receipt_url = "receipt.php?id=" . urlencode($txn['transaction_id']) . "&type=merchandise";  echo "<tr>";  echo "<td>" . $txn['id'] . "</td>";  echo "<td><code>" . htmlspecialchars($txn['transaction_id']) . "</code></td>";  echo "<td>" . htmlspecialchars($txn['customer_name']) . "</td>";  echo "<td>₱" . number_format($txn['total_amount'], 2) . "</td>";  echo "<td>" . htmlspecialchars($txn['validation_status']) . "</td>";  echo "<td>" . date('M j, Y g:i A', strtotime($txn['created_at'])) . "</td>";  echo "<td><a href='" . $receipt_url . "' target='_blank'>View Receipt</a></td>";  echo "</tr>";  }  echo "</table>";  // Test the bad URL  echo "<hr>";  echo "<h3>Debug Test:</h3>";  echo "<p>The URL you tried: <a href='receipt.php?id=MERCH202612535096&type=merchandise' target='_blank'>receipt.php?id=MERCH202612535096&type=merchandise</a></p>";  echo "<p>This should work with fuzzy matching now (it will find MERCH2026125350963)</p>";  } else {  echo "<p style='color:red;'>No transactions found. Create a new transaction first.</p>";  }  } catch (Exception $e) {  echo "<p style='color:red;'>Error: " . htmlspecialchars($e->getMessage()) . "</p>";
}  echo "</body></html>";
